const raw = ($input.first().json.output || '').toString();

// Referencia tolerante al nombre del nodo: n8n le agrega un "1" (o "2", "3"...)
// cada vez que pegás un nodo con un nombre que ya existe en el canvas. En vez
// de perseguir el nombre exacto cada vez, probamos una lista de variantes.
function leerOrigen(nombres) {
  for (const nombre of nombres) {
    try {
      const item = $(nombre).first();
      if (item) return item.json;
    } catch (e) {
      // este nodo no corrio en esta ejecucion (o no existe con ese nombre), seguimos probando
    }
  }
  return null;
}

const origenChat = leerOrigen(['When chat message received', 'When chat message received1']);
const origenEmail = leerOrigen(['Preparar email entrante', 'Preparar email entrante1']);
const origenTrigger = leerOrigen(['Trigger: Email entrante', 'Trigger: Email entrante1']);
const original = origenChat || origenEmail || {};

// El remitente real viene de la cabecera 'from' del Gmail Trigger, nunca del
// texto del cuerpo -- la IA solo lo devuelve si el remitente se auto-menciono
// explicitamente, que es la excepcion, no la regla. 'Preparar email entrante'
// ya expone ese dato como 'email' (confirmado que resuelve bien), asi que lo
// leemos de ahi primero, con el trigger como respaldo.
let remitenteReal = null;
const emailCrudo = (origenEmail && origenEmail.email) || (origenTrigger && origenTrigger.from) || null;
if (emailCrudo) {
  const match = emailCrudo.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  remitenteReal = match ? match[0] : emailCrudo;
}

// El nombre visible del remitente sale de la misma cabecera 'from', que trae
// el formato "Nombre Apellido <email@dominio>". Sacamos la parte del email
// entre <> y nos quedamos con lo que sobra.
let nombreReal = null;
const fromCrudo = (origenTrigger && origenTrigger.from) || (origenEmail && origenEmail.email) || null;
if (fromCrudo) {
  const soloNombre = fromCrudo.replace(/<[^>]*>/g, '').trim();
  if (soloNombre) nombreReal = soloNombre;
}

// Umbral de confianza. Arranca alto y conservador: cualquier categoria de
// accion por debajo de este numero se degrada a REVISION. Se baja recien
// cuando haya datos reales del acierto del clasificador.
const UMBRAL_CONFIANZA = 0.8;
const CATEGORIAS_VALIDAS = ['VUELOS', 'COMPRA', 'OTROS', 'REVISION'];

let data;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  data = JSON.parse(cleaned);
} catch (e) {
  data = null;
}

let motivo_revision = null;

// Guardia 1 - Taxonomia cerrada: salida fuera de las 4 categorias, o
// parseo fallido, se fuerza a REVISION. Nunca se deja pasar valor libre.
if (!data || !CATEGORIAS_VALIDAS.includes(data.categoria)) {
  data = {
    categoria: 'REVISION',
    confianza: 0,
    asunto: (data && data.asunto) || '(sin asunto)',
    remitente: (data && data.remitente) || null
  };
  motivo_revision = 'salida_invalida';
}

const n = Number(data.confianza);
const confianza = Number.isFinite(n) ? n : 0;

// Guardia 2 - Umbral: solo degrada categorias de accion. Si el modelo ya
// dijo REVISION, se respeta aunque venga con confianza alta (esta seguro
// de que el caso es ambiguo, que es exactamente lo que se le pidio).
let categoria_sugerida = null;
if (data.categoria !== 'REVISION' && confianza < UMBRAL_CONFIANZA) {
  categoria_sugerida = data.categoria;
  data.categoria = 'REVISION';
  motivo_revision = 'confianza_bajo_umbral';
}

return [{
  json: {
    categoria: data.categoria,
    categoria_sugerida,
    confianza,
    umbral: UMBRAL_CONFIANZA,
    motivo_revision,
    asunto: data.asunto || '(sin asunto)',
    remitente: remitenteReal || data.remitente || null,
    nombre: nombreReal || ((data.remitente && !data.remitente.includes('@')) ? data.remitente : null),
    body: original.chatInput || original.body || ''
  }
}];

const paises = $('Delegar a Worker Compra').first().json.data.paises_mencionados || [];
const catalogo = $('Leer catálogo de tours').all().map(item => item.json);

// Normaliza texto para comparar tolerando acentos y mayusculas/minusculas
function normalizar(texto) {
  return (texto || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

// Equivalencias entre nombres de pais en distintos idiomas -- sumar mas si hace falta
const equivalencias = {
  'brasil': 'brazil'
};

function paisNormalizado(pais) {
  const n = normalizar(pais);
  return equivalencias[n] || n;
}

let toursFiltrados;
if (!paises || paises.length === 0) {
  // Sin pais mencionado -> se devuelven todos los tours del catalogo
  toursFiltrados = catalogo;
} else {
  const paisesPedidos = paises.map(paisNormalizado);
  toursFiltrados = catalogo.filter(tour => paisesPedidos.includes(paisNormalizado(tour['Pais'])));
}

return [{
  json: {
    pais_solicitado: (paises && paises.length > 0) ? paises.join(', ') : null,
    tours: toursFiltrados.map(t => ({
      pais: t['Pais'],
      nombre_tour: t['Nombre del Tour'],
      fecha_salida: t['Fecha de Salida'],
      duracion_dias: t['Duracion (dias)'],
      costo_usd: t['Costo (USD)'],
      cupos_disponibles: t['Cupos Disponibles'],
      descripcion: t['Descripcion breve']
    }))
  }
}];
